"""Example-driven Python function synthesizer."""
import re


def extract(text):
    blocks = re.findall(r"```(?:python|py)?\s*\n(.*?)```", text, re.DOTALL | re.IGNORECASE)
    return blocks[-1].strip() if blocks else text.strip()


def solve(task, api):
    examples = "\n".join(
        f"f({ex['input']!r}) == {ex['output']!r}" for ex in task["examples"]
    )
    prompt = (
        "Infer the intended general transformation from ALL the examples below. "
        "The examples are generated by a small deterministic list-processing rule. "
        "Do not memorize examples. Consider ordering, duplicates, positions, "
        "neighboring elements, arithmetic, counts, and boundary cases. "
        "Check your proposed rule by manually tracing every example. "
        "Prefer a simple rule that explains all outputs exactly.\n\n"
        + examples
        + "\n\nReturn only Python source defining def f(xs), in a Python code block."
    )
    system = "You are an expert at inferring precise list algorithms from examples."
    code = ""
    try:
        code = extract(api.llm(prompt, system=system))
    except api.BudgetExceeded:
        return code

    report = None
    try:
        report = api.check(code)
    except api.BudgetExceeded:
        pass

    failures = [r for r in report or [] if not r["passed"]]
    review = (
        "Independently scrutinize this inferred function against the examples. "
        "First reason about alternative simple rules, including index-dependent "
        "rules and the handling of ties and boundaries. Identify any unjustified "
        "assumptions. Then choose the most plausible general rule and implement it. "
        "It must match every example, not just some. Return only Python code "
        "defining def f(xs), in a Python code block.\n\n"
        + examples + "\n\nCandidate:\n```python\n" + code + "\n```"
    )
    if failures:
        review += "\nThe candidate fails these checks:\n" + "\n".join(
            f"input={r['input']!r}, expected={r['expected']!r}, actual={r['actual']!r}"
            for r in failures
        )
    try:
        revised = extract(api.llm(review, system=system))
    except api.BudgetExceeded:
        return code

    try:
        revised_report = api.check(revised)
    except api.BudgetExceeded:
        return revised if failures else code
    revised_failures = [r for r in revised_report if not r["passed"]]
    if not revised_failures:
        return revised
    if not failures and report is not None:
        return code

    repair = (
        "Fix this function so it matches every example. Infer the general rule "
        "rather than hard-coding inputs. Return only Python code defining f(xs).\n\n"
        + examples + "\n\nCode:\n" + revised + "\n\nFailures:\n"
        + "\n".join(
            f"input={r['input']!r}, expected={r['expected']!r}, actual={r['actual']!r}"
            for r in revised_failures
        )
    )
    try:
        fixed = extract(api.llm(repair, system=system))
        try:
            fixed_report = api.check(fixed)
            if all(r["passed"] for r in fixed_report):
                return fixed
        except api.BudgetExceeded:
            return fixed
    except api.BudgetExceeded:
        pass
    if report is not None and len(failures) < len(revised_failures):
        return code
    return revised
